    for rule in rules:
        sort_order, field = rule.split(' ')
        column = columns[columns.index(field)]

        for key in sorted(final_table.keys()):
            if sort_order == 'ASC' and final_table[key]:
                final_table[key].sort()
            elif sort_order == 'DESC' and final_table[key]:
                final_table[key].sort(reverse=True)

    result = [['' for _ in range(len(columns))] for _ in range(len(final_table.keys()))]

    for column, sorted_column in final_table.items():
        row_index = 0
        for sorted_row in sorted_column:
            result[row_index][columns.index(column)] = ' '.join(sorted_row)
            row_index += 1

    for row in result:
        print(' '.join(row))

if __name__ == "__main__":
