import sys
from typing import List

def max_sensors_on_ray(n: int, a: List[int], m: int, b: List[int], y1: int, y2: int) -> int:
    if n == 1 or m == 1:
        return max(a[0], b[0])

    sorted_a = sorted(a)
    sorted_b = sorted(b)

    max_sensors = 0

    i = n - 1  # Start from the last sensor on the first line
    j = 0      # Start from the first sensor on the second line

    while i >= 0 and j < m:
        if sorted_a[i] - sorted_b[j] < y2 - y1:
            i -= 1
        else:
            max_sensors += 1
            j += 1
            i -= 1

    return max(max_sensors, sorted_a[0] - y1)
