class ChessboardGame:
    def __init__(self, n, m):
        self.n = n
        self.m = m
        self.available_white = set()
        self.free_cells = set([(i, j) for i in range(1, 2*n + 1) for j in range(1, 2*m + 1) if (i+j) % 2 == 0])
        self.kings = []

    def is_night(self):
        return len(self.free_cells) > self.n * self.m

    def attempt_placement(self):
        available = self.free_cells - set(self.kings)
        return len(available) >= self.n * self.m

    def mark_cell(self, i, j):
        if (i + j) % 2 == 0:
            self.available_white.remove((i, j))

    def solve(self, queries):
        for query in queries:
            i, j = query
            self.mark_cell(i, j)
            if not self.is_night():
                return "NO"
            if self.attempt_placement():
                return "YES"
        return "NO"

