def is_decomposable(x, n, modulo):
    if (isqrt(x * n) - floor(isqrt(x * n)) == 0):
        return True
    factor = 2
    while (gcd(x, factor) == 1 and factor < floor(isqrt(x * n))):
        factor += 1
    if (factor == floor(isqrt(x * n))):
        return True
    return False

def main():
