    maxn, maxa, q = map(int, input().split())
    modulo = 10**5 + 129

    # Compute x-value for overlapping cases
    k = maxn**2 - 1
    j = k * 2
    V = maxn * maxn
    while (V > k or (V-2)**3 > maxa):
        k -= 2
        V -= 4

    # Solve problem of number of tuples V such that there is a natural number k with gcd V, 1...k = k
    Vu = V - 1
    count = 0
    for i in range(k, 0, -1):
        if Vu/i > i:
            count += 1
    count *= k
    if (count + 1) % 2 != 0:
        count -= 1
    if (count * 2 + 1) % 2 != 0:
        count -= 1
    result = int((i + 1 - is_decomposable(count, k, modulo) and 1 or 0))
    if (min(q, result) < 0):
        return q * int(1.0/(q - (min(q, result))))
    elif (result % 2 == 0):
        return int(1.0 * q/2)
    else:
        return int(1.0 * (q - 1)/2)

