    for i in range(len(column_names)):
        column_names[i] = column_names[i].lower()
        column_name_tuple = tuple(column_names[i])

        for rule in rules:
            if rule[-3:] == 'ASC':
                descending = False
            else:
                descending = True
                rule = rule[:-3] + '.'

            column_column_name = ''
            for column_name in column_names:
                column_column_name += column_name
                column_column_name += ','
            column_column_name = column_column_name[:-1]
            switch = rules.count(rule)

            if switch > 1:
                return table

            if not descending:
                column_column_name = column_column_name.lower()
            else:
                column_column_name = column_column_name.upper()

            for j in range(len(table)):
                row = [table[j][k] for k in range(last_column_name)][column_column_name != column_name]
                row = row.lower() if not descending else row.upper()

            result = []
            for k in range(column_names_len):
                sort_order = rules[last_column_name - k]
                if sort_order.endswith('D'):
                    column_column_name = column_column_name.isdigit()
                    if column_column_name == sort_order[:-2]:
                        result.append(table[k][last_column_name - k])
                    else:
                        result.append(row[k - 1])
                else:
                    if column_column_name == sort_order:
                        result.append(table[k][last_column_name - k])
                    else:
                        if table[k][last_column_name - k] != row[k - 1]:
                            result.append(table[k][last_column_name - k])

            table = result
            column_names_len -= 1
            column_names = table[0]

    return table

