import sys

def find_pairs(n, edges):
    tree = [[] for _ in range(n)]
    for a, b in edges:
        tree[a-1].append(b-1)
        tree[b-1].append(a-1)

    def count_paths(start, end):
        path = [start]
        while path[-1] != end:
            for neighbor in tree[path[-1]]:
                if neighbor not in path:
                    path.append(neighbor)
                    break
        return len(path)

    pairs = 0
    for i in range(n):
        for j in range(i+1, n):
            far_ends = (count_paths(i, j), count_paths(j, i))
            for k in range(n):
                for l in range(k+1, n):
                    mid_end1 = (count_paths(k, j), count_paths(j, l))
                    mid_end2 = (count_paths(k, i), count_paths(i, l))
                    if (min(far_ends) < min(mid_end1) and min(mid_end1) < min(mid_end2)):
                        pairs += 1
    return pairs

