    result = []
    sequences = {}
    for i, j in deletions:
        subtract = 0
        for k, gap in enumerate(sequence):
            if gap < j:
                subtract += 1
                result.append(j)
                sequence[j - 1] = 'gap'
            elif j <= gap:
                result[j - 1] = gap
                sequence[j - 1] = 'gap'
                sequence[subtract] = subtract + 1
            else:
                index = gap // 2
                sequence[index] = index
                if gap - index >= 1 and index > 0:
                    sequence[index - 1] = index - 1

