from collections import defaultdict
from typing import List

def find_minimal_language_word(alphabet: str, n: int, m: int, rules: List[List[int]], s: str) -> str:
    letter_positions = defaultdict(dict)
    for i in range(1, n + 1):
        letter_positions[alphabet[ord(s[i - 1]) - ord('a')]][i] = i

    reverse_positions = defaultdict(list)
    for pos, t1 in rules:
        reverse_positions[1 - ord(alphabet[ord(s[pos - 1]) - ord('a')])].append((pos, t1))

    def backtrack(index: int, remaining_length: int, current_word: str) -> str:
        if index == n and remaining_length == 0:
            return current_word
        if remaining_length < 0:
            return ''

        best_word = ''
        for letter_pos in letter_positions:
            if letter_pos not in reverse_positions or len(reverse_positions[letter_pos]) == 0:
                continue
            for pos, t2 in reverse_positions[letter_pos]:
                word = current_word + s[pos - 1]
                next_index = index
                remaining_length -= 1
                for pos_in_word, letter_pos_in_word in letter_positions[letter_pos]:
                    if next_index < n and letter_pos_in_word != pos + remaining_length:
                        next_index += 1
                    else:
                        word += s[next_index - 1]
                        break
                result = backtrack(next_index, remaining_length, word)
                if result and (best_word == '' or result < best_word):
                    best_word = result
        return best_word

    return backtrack(0, n, '')


