from typing import List

def find_max_length_increasing_subsequence(nums: List[int], gaps: List[int], fill_numbers: List[int], fill_count: int) -> str:
    dp: List[int] = [-1]
    res: List[int] = []
    for i, gap in enumerate(gaps):
        j = i + 1
        while j < len(nums) and nums[j] >= nums[i]:
            j += 1
        if j == len(nums): 
            continue
        val = nums[i] + 1
        insort(dp, val)
        for _ in range(fill_count): 
            if dp[-1] > val + 1: 
                res.append(dp.pop())
            else: 
                dp.append(dp.pop())
    return ' '.join(map(str, res))

if __name__ == "__main__":
