from heapq import heappush, heappop

def can_place_kings(rows, cols):
    """
    Check if it's possible to place kings without attackers for a given configuration.
    """
    # Use a min-heap to keep track of the max height of black squares below any white square.
    heights = [0] * (2 * rows * cols)
    max_heights = [0] * rows
    attackers = max_heights.copy()

    for i in range(rows):
        for j in range(i + 1, rows):
            for k in range(cols * 2 - 1):
                height, attack = (i, k), (True, 0)
                if k % rows == 0 and k < cols * 2 - 1:
                    attack = not attack
                    height = (i + 1, k + 1)
                enemy_height = (max_heights[j] - 1, k)
                heappush(heights, (-height[1], height[0], -attack, enemy_height))

    while heights:
        _, x, is_black, enemy = heappop(heights)
        if is_black and max_heights[j] > enemy[0]:
            return False
        max_heights[j] = enemy[0]
        if enemy[1] > cols * 2 - 1:
            attackers[j] = False

    return True

def solve():
