    """
    Finds the maximum total value of a valid sequence of blocks.
    """
    def is_valid(top_left, bottom_right, blocks):
        dx1, dy1, dx2, dy2 = blocks[0][3] - blocks[0][2], 1, blocks[-1][3] - blocks[-1][2], 1
        dx3, dy3, dx4, dy4 = blocks[blocks.index([0, 0]) + 1][3] - blocks[blocks.index([0, 0]) + 1][2], 1, -1, blocks[-1][3]
        return (
            (blocks[0][0] == blocks[-1][3] and bottom_right[1] == blocks[0][1] and top_left[1] == blocks[-1][1]) or
            (blocks[-1][0] == blocks[0][3] and top_left[1] == blocks[-1][1] and bottom_right[1] == blocks[0][1]) or
            (blocks[0][0] == blocks[-1][3] and top_left[0] == blocks[0][2] and bottom_right[0] == blocks[-1][2]) or
            (blocks[0][0] == blocks[-1][3] and bottom_right[0] == blocks[0][2] and top_left[0] == blocks[-1][2])
        )

    def dp(index: int, width: int, height: int) -> int:
        dp = [[-float("inf")] * (width + 1) for _ in range(height + 1)]
        dp[0][-1] = blocks[index][-1]
        for w in range(width):
            idx = blocks[index][2]
            for h in range(height):
