                        dp[idx][w] = max(dp[idx][w], dp[idx][k] + blocks[index][k])
                    for k in range(h, height):
                        dp[idx][w] = max(dp[idx][w], dp[idx][k] + blocks[index][k])
                    break
        return dp[-1][-1]

