def max_registrations(n, y1, a, m, y2, b):
    if n < m:
        return n
    elif n > m + 1:
        return m

    if max(a) < min(b) or max(b) < min(a):
        return min(n, m)

    y = y1 + (y2 - y1) * (m - n) / (n + m)
    x = (n * (y - y2) + m * (y - y1)) / (n + m)

    count = 0

    for ai, bi in zip(a, b):
        yi, xi = y1 + 0, y2 + 0
        while yi <= yi + ai + bi:
            for y in range(yi, yi + ai + bi, ai):
                for x in range(x, max(xi, 0), min(xi - x, ai)):
                    if abs(y - yi) % ai == abs(x - xi) % ai:
                        count += 1
