from collections import defaultdict

def bfs(graph, start):
    distances = defaultdict(lambda: float('inf'))
    distances[start] = 0
    queue = [start]
    while queue:
        current = queue.pop(0)
        for neighbor, distance in graph[current]:
            if distances[neighbor] > distance + distances[current]:
                distances[neighbor] = distance + distances[current]
                queue.append(neighbor)
    return distances

def count_paths(graph):
    distances = bfs(graph, 1)
    n = len(distances)
    answer = 0
    for n1 in range(1, n):
