from typing import List

def longest_increasing_subsequence_length(array: List[int]) -> int:
    dp = [1] * len(array)
    for i in range(1, len(array)):
        for j in range(i):
            if array[i] > array[j]:
                dp[i] = max(dp[i], dp[j] + 1)
    return max(dp)

def solve(gaps: List[int], fill_numbers: List[int], n: int, m: int) -> List[int]:
    gaps = [n + i if x == -1 else x for i, x in enumerate(gaps)]
    for i, x in enumerate(gaps):
        if x >= m: break
        gaps[i] = x
    gaps.sort()
    sorted_fill_numbers = sorted(set(fill_numbers))

    max_length = longest_increasing_subsequence_length(gaps)

    if max_length >= n:
        return fill_numbers[:n]

    remaining_elements = n - max_length
    remaining_indices = [i for i, x in enumerate(gaps) if x < m]
    for i, max_gap_index in enumerate(remaining_indices):
        for j, fill_number in enumerate(sorted_fill_numbers):
            if gaps[max_gap_index] + j < m:
                gaps[max_gap_index] = gaps[max_gap_index] + j
                fill_numbers[i * remaining_elements + j] = fill_number
                break

    for i in range(n):
        if gaps[i] < m:
            for j, fill_number in enumerate(sorted_fill_numbers):
                if gaps[i] + j < m:
                    gaps[i] = gaps[i] + j
                    fill_numbers[i] = fill_number
                    break

    while True:
        max_length = longest_increasing_subsequence_length(gaps)
        if max_length < n:
            break
        remaining_elements = n - max_length
        remaining_indices = [i for i, x in enumerate(gaps) if x < m]
        for i, max_gap_index in enumerate(remaining_indices):
            for j, fill_number in enumerate(sorted_fill_numbers):
                if gaps[max_gap_index] + j < m:
                    gaps[max_gap_index] = gaps[max_gap_index] + j
                    fill_numbers[i * remaining_elements + j] = fill_number
                    break

    return fill_numbers

if __name__ == "__main__":
    n = int(input())
    array = list(map(int, input().split()))
    m = int(input())
    fill_numbers = list(map(int, input().split()))
    answer = solve(array, fill_numbers, n, m)
    for num in answer:
        print(num, end=" ")
    print()
