    while True:
        rule = input().strip()
        if rule:
            pos1, t1, pos2, t2 = rule.split()
            rules.append((int(pos1), 'V' if t1 == 'V' else 'C', int(pos2), 'VC' if t2 == 'VC' else 'V'))
        else:
            break
    return rules

def lexicographical_order(l, s, rules):
    alphabet = {0: '', 1: 'a', 2: 'b', 3: 'c', 4: 'd', 5: 'e', 6: 'f', 7: 'g', 8: 'h', 9: 'i', 10: 'j', 11: 'k', 12: 'l', 13: 'm', 14: 'n', 15: 'o', 16: 'p', 17: 'q', 18: 'r', 19: 's', 20: 't', 21: 'u', 22: 'v', 23: 'w', 24: 'x', 25: 'y', 26: 'z'}
    letters = ['V', 'C']
    positions = defaultdict(set)
    for pos1, t1, pos2, t2 in rules:
        positions[t1].add(pos1)
        positions[t2].add(pos2)

    for i in range(len(s)):
        if s[i] in letters:
            letters.remove(s[i])
        for pos in positions[s[i]]:
            s[pos], s[pos1 - 1] = s[pos1 - 1], s[pos]
            if s[i] in letters:
                letters.remove(s[i])
    return l - len(s)

def find_minimal_word(l, n, rules, s):
    words = {s}
    for i in range(1, n + 1):
        for position, t1, position1, t2 in rules:
            for pos_s, pos2_s in zip(range(len(s)), range(len(s))):
                if pos_s in letters[t1] and pos2_s in letters[t2]:
                    words.add(s[:pos_s] + s[pos_s + 1:pos2_s] + s[pos2_s + 1:len(s)] + s[pos_s] + s[pos1 - 1] + s[pos1] + s[pos2_s + 1:position] + s[pos_s])
    words = sorted(word for word in words if word >= s)
    return words[0] if words else -1

