    return graph

def dijkstra(graph, start):
    distance = {node: float('inf') for node in graph}
    distance[start] = 0
    priority_queue = [(0, start)]

    while priority_queue:
        current_distance, current_node = heapq.heappop(priority_queue)

        if current_distance > distance[current_node]:
            continue

        for neighbor, weight in graph[current_node]:
            distance[neighbor] = min(distance[neighbor], current_distance + weight)
            heapq.heappush(priority_queue, (distance[neighbor], neighbor))

    return distance

def get_subgraph_and_path(graph, start, end):
    distance = dijkstra(graph, start)
    subgraph = {}
    path = deque([])

    current, t = start, 0

    while distance[current] != float('inf') and current != end:
        v, new_t = graph[current].pop(0)
        subgraph[t] = ([v, new_t], [current, t])
        current = v
        t = new_t

    return subgraph, dist_start_to_end

def main():
    graph = read_graph()
    dist_start_to_end = dijkstra(graph, 1)
    subgraph, path = get_subgraph_and_path(graph, 1, 1)

    for v, t in path:
        print('%d %d'% (v, t))

if __name__ == "__main__":
    main()
