from typing import List

def sort_table(table: List[List[str]], rules: List[str]) -> None:
    """
    Sorts the table rows based on the given sorting rules.
    """
    columns = {rule.split()[0]: 1 for rule in rules if rule}
    for column_name in columns:
        column_index = columns[column_name]
        sorted_index = column_index
        while sorted_index + 1 < len(table[0]) and table[0][sorted_index].isdigit():
            sorted_index += 1
        for row in table:
            if row[column_index] == row[sorted_index]:
                row[column_index], row[sorted_index] = sorted_index, column_index
            else:
                row[sorted_index] = column_index

